mapper.update:
UPDATE SYS_USER
SET FIRST_LOGIN = #{status,jdbcType=VARCHAR}
WHERE USER_ID = #{userId,jdbcType=DECIMAL}

mapper.select:
SELECT , , SU.EMPLOYEE_ID, HE.EMPLOYEE_CODE EMPLOYEE_CODE, HE.NAME EMPLOYEE_NAME FROM SYS_USER SU LEFT OUTER JOIN FND_EMPLOYEE HE ON SU.EMPLOYEE_ID = HE.EMPLOYEE_ID
AND SU.USER_ID=#{userId}
AND SU.USER_NAME LIKE concat('%', concat(#{userName,jdbcType=VARCHAR}, '%'))
AND SU.USER_TYPE=#{userType}
AND SU.DESCRIPTION Like concat('%', concat(#{description}, '%'))
ORDER BY SU.${_colName} ${sortorder}
ORDER BY SU.USER_ID ASC

SELECT SU.USER_ID, SU.USER_NAME, SU.EMPLOYEE_ID, su.bp_id, su.bp_category, hbm.bp_name bp_name, case su.bp_category when 'VENDER' then (select hbm1.bp_id from hls_bp_master_relation hbmr,hls_bp_master hbm1 where hbmr.bp_id = hbm.bp_id and hbmr.relation_type = 'MANUFACTURER' and hbmr.related_bp_id=hbm1.bp_id AND rownum = 1) when 'DEALER' then (select hbm2.bp_id from hls_bp_master_relation hbmr1,hls_bp_master hbm2 where hbmr1.relation_type = 'MANUFACTURER' and hbmr1.related_bp_id = hbm2.bp_id and hbmr1.admit_status in('APPROVED','FAILURE') and hbmr1.enabled_flag = 'Y' and hbmr1.bp_id = (select hbm1.bp_id from hls_bp_master_relation hbmr,hls_bp_master hbm1 where hbmr.bp_id = hbm.bp_id and hbmr.relation_type = 'VENDER' and hbmr.related_bp_id=hbm1.bp_id AND rownum = 1 ) ) else '' end manufacturer_id, (SELECT DISTINCT(fe. NAME) FROM sys_user_allocation sua, fnd_employee_assigns fea, fnd_employee fe WHERE su.USER_ID = sua.user_id AND sua.employee_assign_id = fea.EMPLOYEE_ASSIGN_ID AND fe.EMPLOYEE_ID = fea.EMPLOYEE_ID and fe.ENABLED_FLAG = 'Y' ) EMPLOYEE_NAME, ( SELECT DISTINCT(fe.EMPLOYEE_CODE) FROM sys_user_allocation sua, fnd_employee_assigns fea, fnd_employee fe WHERE su.USER_ID = sua.user_id AND sua.employee_assign_id = fea.EMPLOYEE_ASSIGN_ID AND fe.EMPLOYEE_ID = fea.EMPLOYEE_ID and fe.ENABLED_FLAG = 'Y' ) EMPLOYEE_CODE,SU.EMAIL, SU.PHONE, SU.STATUS,SU.START_ACTIVE_DATE,SU.END_ACTIVE_DATE, SU.DESCRIPTION,SU.USER_TYPE,SU.INTRANET_FLAG,
FROM SYS_USER SU LEFT OUTER JOIN FND_EMPLOYEE HE ON SU.EMPLOYEE_ID = HE.EMPLOYEE_ID LEFT JOIN hls_bp_master hbm on su.bp_id = hbm.bp_id left join ( select hbm.bp_id,hbt.bp_type,hbt.description from hls_bp_master hbm left join hls_bp_type hbt on hbm.bp_type =hbt.bp_type ) temp on su.bp_id =temp.bp_id
Left JOIN SYS_USER_ALLOCATION UR ON SU.USER_ID=UR.USER_ID
AND SU.USER_ID=#{userId}
AND SU.DESCRIPTION like concat('%', concat(#{description}, '%'))
AND SU.USER_NAME LIKE concat('%', concat(#{userName,jdbcType=VARCHAR}, '%'))
AND SU.USER_TYPE=#{userType}
AND temp.bp_type=#{bpType}
AND HE.EMPLOYEE_CODE LIKE concat('%', concat(#{employeeCode,jdbcType=VARCHAR}, '%'))
AND HE.NAME LIKE concat('%', concat(#{employeeName,jdbcType=VARCHAR}, '%'))
AND UR.ROLE_ID=#{roleId}
AND SU.STATUS=#{status}
AND SU.INTRANET_FLAG=#{intranetFlag}
AND (SU.INTRANET_FLAG=#{intranetFlag} or SU.INTRANET_FLAG is null)
ORDER BY SU.${_colName} ${sortorder}
ORDER BY SU.USER_NAME ASC

select distinct sua.user_id
from sys_user_allocation sua
where sua.allocation_id=#{allocationId}

SELECT SU.USER_ID, SU.USER_NAME, SU.EMPLOYEE_ID, su.bp_id, hbm.bp_name bp_name, CASE WHEN ( SELECT COUNT( 1 ) FROM HLS_BP_MASTER_ROLE hbmr WHERE su.bp_id = hbmr.bp_id AND hbmr.BP_CATEGORY = 'DEALER' ) > 0 THEN 'DEALER' ELSE ( SELECT hbmr.bp_category FROM HLS_BP_MASTER_ROLE hbmr WHERE su.bp_id = hbmr.bp_id AND hbmr.PRIMARY_FLAG = 'Y' ) END AS bp_category, case su.bp_category when 'VENDER' then (select hbm1.bp_id from hls_bp_master_relation hbmr,hls_bp_master hbm1 where hbmr.bp_id = hbm.bp_id and hbmr.relation_type = 'MANUFACTURER' and hbmr.related_bp_id=hbm1.bp_id AND rownum = 1) when 'DEALER' then (select hbm2.bp_id from hls_bp_master_relation hbmr1,hls_bp_master hbm2 where hbmr1.relation_type = 'MANUFACTURER' and hbmr1.related_bp_id = hbm2.bp_id and hbmr1.bp_id = (select hbm1.bp_id from hls_bp_master_relation hbmr,hls_bp_master hbm1 where hbmr.bp_id = hbm.bp_id and hbmr.relation_type = 'VENDER' and hbmr.related_bp_id=hbm1.bp_id AND rownum = 1 ) ) else '' end manufacturer_id, (SELECT DISTINCT(fe. NAME) FROM sys_user_allocation sua, fnd_employee_assigns fea, fnd_employee fe WHERE su.USER_ID = sua.user_id AND sua.employee_assign_id = fea.EMPLOYEE_ASSIGN_ID AND fe.EMPLOYEE_ID = fea.EMPLOYEE_ID ) EMPLOYEE_NAME, ( SELECT DISTINCT(fe.EMPLOYEE_CODE) FROM sys_user_allocation sua, fnd_employee_assigns fea, fnd_employee fe WHERE su.USER_ID = sua.user_id AND sua.employee_assign_id = fea.EMPLOYEE_ASSIGN_ID AND fe.EMPLOYEE_ID = fea.EMPLOYEE_ID ) EMPLOYEE_CODE,SU.EMAIL, SU.PHONE, SU.STATUS,SU.START_ACTIVE_DATE,SU.END_ACTIVE_DATE, SU.DESCRIPTION,SU.USER_TYPE, temp.description bp_name_type,
FROM SYS_USER SU LEFT OUTER JOIN FND_EMPLOYEE HE ON SU.EMPLOYEE_ID = HE.EMPLOYEE_ID LEFT JOIN hls_bp_master hbm on su.bp_id = hbm.bp_id left join ( select hbm.bp_id,hbt.bp_type,hbt.description from hls_bp_master hbm left join hls_bp_type hbt on hbm.bp_type =hbt.bp_type ) temp on su.bp_id =temp.bp_id
Left JOIN SYS_USER_ALLOCATION UR ON SU.USER_ID=UR.USER_ID
AND SU.USER_ID=#{userId}
AND SU.DESCRIPTION like concat('%', concat(#{description}, '%'))
AND SU.USER_NAME LIKE concat('%', concat(#{userName,jdbcType=VARCHAR}, '%'))
AND SU.USER_TYPE=#{userType}
AND temp.bp_type=#{bpType}
AND HE.EMPLOYEE_CODE LIKE concat('%', concat(#{employeeCode,jdbcType=VARCHAR}, '%'))
AND HE.NAME LIKE concat('%', concat(#{employeeName,jdbcType=VARCHAR}, '%'))
AND UR.ROLE_ID=#{roleId}
AND SU.STATUS=#{status}
ORDER BY SU.${_colName} ${sortorder}
ORDER BY SU.USER_NAME ASC
